<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js"></script><script>
function decodeData(value){return JSON.parse(decodeURIComponent(escape(atob(value||''))))}
function fillForm(form,row){Object.keys(row).forEach(function(key){var input=form.querySelector('[name="'+key+'"]');if(input)input.value=row[key]??''})}
var bookAdminCatalog=<?=json_encode(array_values($data['books']),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,bookScanner=null,bookScannerRunning=false,lastBookScan='',lastBookScanAt=0;
function resetBook(){stopBookScanner();var f=document.querySelector('#bookModal form');f.reset();f.querySelector('[name="id"]').value='';f.querySelector('[name="import_date"]').value='<?=date('Y-m-d')?>';document.getElementById('bookTitle').textContent='Thêm sách'}
function editBook(button){stopBookScanner();var row=decodeData(button.dataset.book),f=document.querySelector('#bookModal form');fillForm(f,row);document.getElementById('bookTitle').textContent='Sửa sách';bootstrap.Modal.getOrCreateInstance(document.getElementById('bookModal')).show()}
function normalizeBarcode(value){return String(value||'').replace(/[^0-9Xx]/g,'').toUpperCase()}
async function lookupBookByIsbn(code){try{var response=await fetch('https://openlibrary.org/search.json?isbn='+encodeURIComponent(code)+'&fields=title,author_name,publisher,first_publish_year,publish_year,subject&limit=1');if(response.ok){var data=await response.json(),doc=data.docs&&data.docs[0];if(doc&&doc.title)return{title:doc.title,authors:doc.author_name||[],publisher:(doc.publisher||[])[0]||'',year:doc.first_publish_year||(doc.publish_year||[])[0]||'',subject:(doc.subject||[])[0]||'',source:'Open Library'}}catch(error){}
try{var googleResponse=await fetch('https://www.googleapis.com/books/v1/volumes?q='+encodeURIComponent('isbn:'+code)+'&maxResults=1&projection=lite');if(googleResponse.ok){var googleData=await googleResponse.json(),info=googleData.items&&googleData.items[0]&&googleData.items[0].volumeInfo;if(info&&info.title)return{title:info.title,authors:info.authors||[],publisher:info.publisher||'',year:(String(info.publishedDate||'').match(/\d{4}/)||[])[0]||'',subject:(info.categories||[])[0]||'',source:'Google Books'}}catch(error){}
return null}
function fillLookedUpBook(form,book,code){form.querySelector('[name="id"]').value='';form.querySelector('[name="barcode"]').value=code;form.querySelector('[name="title"]').value=book.title||'';form.querySelector('[name="publisher"]').value=book.publisher||'';form.querySelector('[name="publication_year"]').value=book.year||'';if(book.subject)form.querySelector('[name="subject"]').value=book.subject;form.querySelector('[name="quantity"]').value=1;if(book.authors&&book.authors.length){var note=form.querySelector('[name="note"]');note.value='Tác giả: '+book.authors.join(', ')+'\nTra cứu từ '+book.source}}
async function applyScannedBook(decodedText){var code=normalizeBarcode(decodedText),now=Date.now(),status=document.getElementById('bookScanStatus');if(!code)return;if(code===lastBookScan&&now-lastBookScanAt<5000)return;lastBookScan=code;lastBookScanAt=now;var form=document.querySelector('#bookModal form'),match=bookAdminCatalog.find(function(book){return normalizeBarcode(book.barcode)===code||normalizeBarcode(book.code)===code});form.querySelector('[name="barcode"]').value=code;if(match){fillForm(form,match);form.querySelector('[name="quantity"]').value=Math.max(1,parseInt(match.quantity||0,10)+1);document.getElementById('bookTitle').textContent='Cập nhật sách đã có';status.innerHTML='<span class="text-success fw-semibold"><i class="bi bi-check-circle"></i> Đã tìm thấy “'+escapeHtml(match.title||'')+'” trong danh mục. Số lượng được tăng thêm 1.</span>';return}form.querySelector('[name="id"]').value='';document.getElementById('bookTitle').textContent='Đang tra cứu thông tin sách…';status.innerHTML='<span class="text-primary fw-semibold"><span class="spinner-border spinner-border-sm me-1"></span> Đã nhận ISBN '+escapeHtml(code)+', đang tra cứu tên sách…</span>';var found=await lookupBookByIsbn(code);if(found){fillLookedUpBook(form,found,code);document.getElementById('bookTitle').textContent='Thêm sách từ mã vạch';status.innerHTML='<span class="text-success fw-semibold"><i class="bi bi-cloud-check"></i> Đã tìm thấy “'+escapeHtml(found.title)+'” từ '+escapeHtml(found.source)+'. Vui lòng kiểm tra thông tin trước khi lưu.</span>'}else{form.querySelector('[name="barcode"]').value=code;form.querySelector('[name="title"]').value='';document.getElementById('bookTitle').textContent='Thêm sách từ mã vạch';status.innerHTML='<span class="text-warning fw-semibold"><i class="bi bi-exclamation-circle"></i> Đã nhận ISBN '+escapeHtml(code)+' nhưng kho dữ liệu công khai chưa có tên sách này. Vui lòng nhập tên thủ công.</span>'}}
function escapeHtml(value){var d=document.createElement('div');d.textContent=String(value||'');return d.innerHTML}
async function toggleBookScanner(){var panel=document.getElementById('bookScannerPanel');if(bookScannerRunning){stopBookScanner();return}panel.classList.remove('d-none');var status=document.getElementById('bookScanStatus');if(typeof Html5Qrcode==='undefined'){status.textContent='Không tải được bộ quét. Vui lòng kiểm tra mạng hoặc nhập mã vạch thủ công.';return}try{bookScanner=bookScanner||new Html5Qrcode('bookBarcodeReader');await bookScanner.start({facingMode:'environment'},{fps:10,qrbox:{width:280,height:150},aspectRatio:1.777778,formatsToSupport:[Html5QrcodeSupportedFormats.EAN_13,Html5QrcodeSupportedFormats.EAN_8,Html5QrcodeSupportedFormats.UPC_A,Html5QrcodeSupportedFormats.UPC_E]},applyScannedBook,function(){});bookScannerRunning=true;status.textContent='Camera đang hoạt động. Đưa mã vạch vào giữa khung hình.'}catch(error){bookScannerRunning=false;status.textContent='Không mở được camera. Hãy cấp quyền camera hoặc nhập mã vạch thủ công.'}}
async function stopBookScanner(){var panel=document.getElementById('bookScannerPanel');if(bookScanner&&bookScannerRunning){try{await bookScanner.stop()}catch(error){}}bookScannerRunning=false;if(panel)panel.classList.add('d-none')}
var bookModalElement=document.getElementById('bookModal');if(bookModalElement)bookModalElement.addEventListener('hidden.bs.modal',stopBookScanner);
function resetEquipment(){var f=document.querySelector('#equipmentModal form');f.reset();f.querySelector('[name="id"]').value='';f.querySelector('[name="import_date"]').value='<?=date('Y-m-d')?>';document.getElementById('equipmentTitle').textContent='Thêm thiết bị'}
function editEquipment(button){var row=decodeData(button.dataset.equipment),f=document.querySelector('#equipmentModal form');fillForm(f,row);document.getElementById('equipmentTitle').textContent='Sửa thiết bị';bootstrap.Modal.getOrCreateInstance(document.getElementById('equipmentModal')).show()}
var bookCatalog=<?=json_encode(array_values(array_map(function($book)use($data){return ['id'=>$book['id']??'','title'=>$book['title']??'','code'=>$book['code']??'','category'=>$book['category']??'','grade'=>(string)($book['grade']??''),'available'=>lib_book_available($book,$data['loans'])];},$data['books'])),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
function currentLoanMode(){var checked=document.querySelector('[name="loan_mode"]:checked');return checked?checked.value:'other'}
function refreshBookSuggestions(){var list=document.getElementById('bookQuickList');if(!list)return;var mode=currentLoanMode(),classSelect=document.getElementById('textbookClass'),grade=classSelect&&classSelect.selectedOptions[0]?String(classSelect.selectedOptions[0].dataset.grade||''):'';list.innerHTML='';bookCatalog.filter(function(book){if(book.available<1)return false;if(mode==='textbook')return book.category==='Sách giáo khoa'&&grade!==''&&String(book.grade).replace(/\D/g,'')===String(grade).replace(/\D/g,'');return book.category!=='Sách giáo khoa'}).forEach(function(book){var option=document.createElement('option');option.value=book.title+(book.code?' — '+book.code:'');option.dataset.id=book.id;option.textContent=book.category+' · còn '+book.available;list.appendChild(option)});document.querySelectorAll('.book-loan-row').forEach(function(row){row.querySelector('.book-quick').value='';row.querySelector('[name="book_id[]"]').value=''})}
function switchLoanMode(){var textbook=currentLoanMode()==='textbook';document.getElementById('textbookBorrower').classList.toggle('d-none',!textbook);document.getElementById('otherBorrower').classList.toggle('d-none',textbook);document.getElementById('textbookClass').required=textbook;document.getElementById('borrowerName').required=!textbook;document.getElementById('bookSuggestionNote').textContent=textbook?'Chọn lớp để hệ thống chỉ gợi ý sách giáo khoa đúng khối.':'Chỉ hiển thị sách tham khảo, sách truyện, báo, tạp chí và tài liệu khác.';refreshBookSuggestions()}
function selectTextbookClass(){var select=document.getElementById('textbookClass'),option=select.selectedOptions[0];document.getElementById('homeroomTeacherDisplay').value=option?option.dataset.teacher||'':'';refreshBookSuggestions()}
function addBookRow(){var wrap=document.getElementById('bookLoanRows'),row=document.createElement('div');row.className='row g-2 align-items-center mb-2 book-loan-row';row.innerHTML='<div class="col-lg-5"><input class="form-control book-quick" list="bookQuickList" placeholder="Gõ hoặc chọn tên sách" required><input type="hidden" name="book_id[]"></div><div class="col-3 col-lg-1"><input class="form-control" type="number" min="1" name="quantity[]" value="1" title="Số lượng" required></div><div class="col-5 col-lg-2"><select class="form-select" name="book_condition[]"><option>Tốt</option><option>Đã qua sử dụng</option><option>Cũ</option><option>Rách nhẹ</option></select></div><div class="col col-lg-3"><input class="form-control" name="book_note[]" placeholder="Ghi chú"></div><div class="col-auto"><button class="btn btn-outline-danger" type="button" onclick="this.closest(\'.book-loan-row\').remove()"><i class="bi bi-x-lg"></i></button></div>';wrap.appendChild(row);row.querySelector('.book-quick').addEventListener('change',resolveBookRow)}
function resolveBookRow(){var value=this.value.trim().toLowerCase(),option=Array.from(document.querySelectorAll('#bookQuickList option')).find(function(o){return o.value.trim().toLowerCase()===value}),row=this.closest('.book-loan-row');row.querySelector('[name="book_id[]"]').value=option?option.dataset.id:'';this.setCustomValidity(option?'':'Hãy chọn đúng tên sách trong danh sách gợi ý.')}
var loanModal=document.getElementById('loanModal');if(loanModal)loanModal.addEventListener('show.bs.modal',function(){var wrap=document.getElementById('bookLoanRows');if(wrap&&!wrap.children.length)addBookRow();switchLoanMode()});
function openReturn(button){var row=decodeData(button.dataset.loan);document.getElementById('returnId').value=row.id||'';document.getElementById('returnBatchId').value=row.batch_id||'';document.getElementById('returnInfo').textContent=row.borrower_name+' — '+row.item_count+' đầu sách, tổng '+row.total_quantity+' cuốn. Thao tác này sẽ trả toàn bộ sách trong phiếu.';bootstrap.Modal.getOrCreateInstance(document.getElementById('returnModal')).show()}
var borrower=document.getElementById('borrowerName');if(borrower)borrower.addEventListener('change',function(){var options=Array.from(document.querySelectorAll('#borrowerList option')),needle=this.value.trim().toLowerCase(),match=options.find(function(o){return o.value.trim().toLowerCase()===needle||o.dataset.code.toLowerCase()===needle});document.getElementById('borrowerId').value=match?match.dataset.id:'';document.getElementById('borrowerType').value=match?match.dataset.type:'manual';document.getElementById('borrowerClass').value=match?match.dataset.class:''});
function addEquipmentRow(){var wrap=document.getElementById('equipmentLoanRows'),row=document.createElement('div');row.className='row g-2 align-items-center mb-2 equipment-loan-row';row.innerHTML='<div class="col-lg-4"><input class="form-control equipment-quick" list="equipmentQuickList" placeholder="Gõ tên hoặc mã thiết bị" required><input type="hidden" name="equipment_id[]"></div><div class="col-3 col-lg-1"><input class="form-control" type="number" min="1" name="equipment_quantity[]" value="1" title="Số lượng" required></div><div class="col-4 col-lg-2"><input class="form-control" name="lesson_period[]" placeholder="Tiết dạy"></div><div class="col-4 col-lg-2"><input class="form-control" name="teaching_grade[]" placeholder="Khối/lớp dạy"></div><div class="col col-lg-2"><input class="form-control" name="equipment_item_note[]" placeholder="Ghi chú"></div><div class="col-auto"><button class="btn btn-outline-danger" type="button" onclick="this.closest(\'.equipment-loan-row\').remove()"><i class="bi bi-x-lg"></i></button></div>';wrap.appendChild(row);row.querySelector('.equipment-quick').addEventListener('change',function(){var value=this.value.trim().toLowerCase(),option=Array.from(document.querySelectorAll('#equipmentQuickList option')).find(function(o){return o.value.trim().toLowerCase()===value});row.querySelector('[name="equipment_id[]"]').value=option?option.dataset.id:'';this.setCustomValidity(option?'':'Hãy chọn đúng thiết bị trong danh sách gợi ý.')})}
var equipmentLoanModal=document.getElementById('equipmentLoanModal');if(equipmentLoanModal)equipmentLoanModal.addEventListener('show.bs.modal',function(){var wrap=document.getElementById('equipmentLoanRows');if(wrap&&!wrap.children.length)addEquipmentRow()});
function openEquipmentReturn(button){var row=decodeData(button.dataset.eqloan);document.getElementById('equipmentReturnId').value=row.id;document.getElementById('equipmentReturnInfo').textContent=row.borrower+' — '+row.equipment_name+' ('+row.quantity+')';bootstrap.Modal.getOrCreateInstance(document.getElementById('equipmentReturnModal')).show()}
var qrStream=null,qrTimer=null;
function resolveQr(text){var raw=String(text||''),code=raw;try{var u=new URL(raw);code=u.searchParams.get('code')||u.searchParams.get('id')||u.pathname.split('/').filter(Boolean).pop()||raw}catch(e){}var options=Array.from(document.querySelectorAll('#borrowerList option')),needle=String(code).trim().toLowerCase(),match=options.find(function(o){return o.dataset.code.toLowerCase()===needle||o.dataset.id.toLowerCase()===needle});if(!match)return false;borrower.value=match.value;borrower.dispatchEvent(new Event('change'));stopQr();bootstrap.Modal.getInstance(document.getElementById('qrModal')).hide();return true}
async function openQr(){var modal=bootstrap.Modal.getOrCreateInstance(document.getElementById('qrModal'));modal.show();var msg=document.getElementById('qrMessage');if(!('BarcodeDetector'in window)){msg.textContent='Trình duyệt chưa hỗ trợ quét QR trực tiếp. Hãy nhập mã học sinh vào ô Người mượn.';return}try{qrStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});var video=document.getElementById('qrVideo');video.srcObject=qrStream;await video.play();var detector=new BarcodeDetector({formats:['qr_code']});qrTimer=setInterval(async function(){try{var codes=await detector.detect(video);if(codes.length&&!resolveQr(codes[0].rawValue))msg.textContent='Đã đọc QR nhưng chưa tìm thấy học sinh trong CSDL.'}catch(e){}},500)}catch(e){msg.textContent='Không mở được camera. Vui lòng cấp quyền camera hoặc nhập mã thủ công.'}}
function stopQr(){if(qrTimer)clearInterval(qrTimer);qrTimer=null;if(qrStream)qrStream.getTracks().forEach(function(t){t.stop()});qrStream=null}
</script></body></html>